from soils.soil_mechanics import *
from soils.constants import *
from soils.soil_enum import *
from hydraulics.fittings import *
from structures.concrete import *
import questionary as q
import math
from typing import Optional

# --- Calculation Helpers ---

def calculate_pressure_net_block_uncemented_coarse(
    factor_displacement_limitation: float,
    depth_submerged: float,
    height_thrust_block: float,
    buoyancy_coefficient: float,
    internal_friction_angle_soil: float,
    unit_weight_soil: float,
    depth_ground_level_to_top_groundwater_level: float = 0,
    unit_weight_water: float = 10,
) -> float:
    """
    Calculate net pressure on uncemented coarse thrust block (C816, Sect. 3.6.1).
    """
    buoyancy_coef = calculate_buoyancy_coefficient(depth_ground_level_to_top_groundwater_level, depth_submerged)
    coeff_passive = calculate_coefficient_passive_earth_pressure(internal_friction_angle_soil)
    coeff_active = calculate_coefficient_active_earth_pressure(internal_friction_angle_soil)
    net_weight = unit_weight_soil - (buoyancy_coef * unit_weight_water)
    avg_depth = depth_submerged - height_thrust_block / 2
    delta_coeff = coeff_passive - coeff_active

    if factor_displacement_limitation == 0:
        raise ValueError("factor_displacement_limitation must be non-zero.")

    return (net_weight * avg_depth * delta_coeff) / factor_displacement_limitation

def calculate_sliding_resistance_tb_coarse(
    sliding_resistance_dfs: float,
    unit_weight_soil: float,
    buoyancy_coefficient: float,
    depth_submerged: float,
    friction_angle_soil: float,
    unit_weight_water: float = 10,
) -> float:
    """
    Calculate base sliding resistance for uncemented coarse soils (C816, Sect. 3.7.1).
    """
    net_weight = unit_weight_soil - (buoyancy_coefficient * unit_weight_water)
    tan_phi = math.tan(math.radians(friction_angle_soil))
    if sliding_resistance_dfs == 0:
        raise ValueError("sliding_resistance_dfs must be non-zero.")
    return (net_weight * depth_submerged * tan_phi) / sliding_resistance_dfs

def calculate_sliding_resistance_ts(
    sliding_resistance_dfs: float,
    unit_weight_soil: float,
    buoyancy_coefficient: float,
    depth_submerged: float,
    height_thrust_block: float,
    active_earth_pressure_coefficient: float,
    friction_angle_soil: float,
    unit_weight_water: float = 10,
) -> float:
    """
    Calculate side sliding resistance for uncemented coarse soils (C816, Sect. 3.7.2).
    """
    net_weight = unit_weight_soil - (buoyancy_coefficient * unit_weight_water)
    avg_depth = depth_submerged - height_thrust_block / 2
    tan_phi = math.tan(math.radians(friction_angle_soil))
    if sliding_resistance_dfs == 0:
        raise ValueError("sliding_resistance_dfs must be non-zero.")
    return (net_weight * avg_depth * active_earth_pressure_coefficient * tan_phi) / sliding_resistance_dfs

# --- Questionary Helpers ---

def select_enum(prompt: str, enum_cls):
    """Display a questionary select for an enum (returns enum member)."""
    choices = {member.name.replace('_', ' ').title(): member for member in enum_cls}
    selected = q.select(prompt, choices=list(choices.keys())).ask()
    return choices[selected]

def select_soil_type(category):
    """Select a soil type based on category (returns enum member)."""
    types = {st.label.title(): st for st in SoilType if st.category == category}
    selected = q.select("Select soil type:", choices=list(types.keys())).ask()
    return types[selected]

def select_consistency(category):
    """Select consistency based on category (returns enum member)."""
    consistencies = {c.label.title(): c for c in Consistency if c.category == category}
    selected = q.select("Select soil consistency:", choices=list(consistencies.keys())).ask()
    return consistencies[selected]

def get_float_input(prompt: str, min_value: float = 0.0) -> float:
    """Safely get a validated float input from the user."""
    val = q.text(prompt, validate=lambda v: v.replace('.', '', 1).isdigit() and float(v) >= min_value).ask()
    try:
        return float(val)
    except Exception:
        raise ValueError(f"Invalid input for {prompt}")

# --- Main CLI ---

def main():
    fitting_type = q.select(
        "Select fitting type:",
        choices=[
            "Horizontal Bend", "Vertical Bend", "Tee", "Angle Branch",
            "Closed Valve", "Blank End", "Taper Thrust"
        ]
    ).ask()

    maximum_design_pressure = get_float_input("Enter maximum design pressure (kPa):", min_value=0.01)

    soil_category = select_enum("Select soil category:", SoilCategory)
    soil_type = select_soil_type(soil_category)
    consistency = select_consistency(soil_category)

    print(f"You selected: {fitting_type}")
    print(f"Max design pressure: {maximum_design_pressure} kPa")
    print(f"Soil: {soil_category.name}, type: {soil_type.label}, consistency: {consistency.label}")

    # Continue with further inputs/calculations as needed...

if __name__ == "__main__":
    main()